def flood(I,outval):
    H,W=I.shape; out=I.copy(); bg=next(c for c in set(I.ravel()) if c>max(0,I.ravel().argmin()))
    cnt=np.bincount(I.ravel(),minlength=10); bgcol=cnt.argmax()
    R=np.full((H,W),False); stack=[]
    for i in (0,H-1):
        for j in range(W):
            if I[i,j]!=bgcol: continue
            R[i,j]=True;stack.append((i,j))
    for j in (0,W-1):
        for i in range(H):
            if I[i,j]!=bgcol: continue
            R[i,j]=True;stack.append((i,j))
    while stack:
        a,b=stack.pop()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if 0<=x<H and 0<=y<W and not R[x,y] and I[x,y]!=bgcol:
                R[x,y]=True;stack.append((x,y))
    out[(~R) & (I==bgcol)]=outval
    return out
